from orderfeed.app import build_app
from orderfeed.util.clock import FakeClock


class Shop:
    """An app plus an independent record of which orders should be active."""

    def __init__(self, orders=12, step=60):
        self.clock = FakeClock()
        self.app = build_app(clock=self.clock)
        self.expected = {}
        for i in range(orders):
            self.clock.advance(step)
            self.place(f"customer-{i}", 1000 + i)

    def place(self, customer, amount, created_at=None, channel="web"):
        params = {"customer": customer, "amount": amount, "channel": channel}
        if created_at is not None:
            params["created_at"] = created_at
        resp = self.app.post("/orders", params)
        assert resp.status == 200, resp.body
        self.expected[resp.body["id"]] = resp.body
        return resp.body

    def cancel(self, order_id):
        resp = self.app.post(f"/orders/{order_id}/cancel")
        assert resp.status == 200, resp.body
        del self.expected[order_id]

    def newest_first(self):
        return sorted(self.expected, key=lambda i: (self.expected[i]["created_at"], i), reverse=True)


class InterferingTransport:
    """Calls the API like the real client, and runs `action` once right after the n-th listing call."""

    def __init__(self, app, after_call=1, action=None):
        self.app = app
        self.after_call = after_call
        self.action = action
        self.calls = 0

    def __call__(self, path, params):
        resp = self.app.get(path, params)
        self.calls += 1
        if self.action is not None and self.calls == self.after_call:
            action, self.action = self.action, None
            action()
        return resp
"""Order lifecycle."""
from orderfeed.models import InvalidRequest, NotFound


class OrderService:
    CHANNELS = {"web", "app", "pos"}

    def __init__(self, store, clock):
        self.store = store
        self.clock = clock

    def create(self, customer, amount, channel="web", created_at=None):
        if channel not in self.CHANNELS:
            raise InvalidRequest(f"unknown channel {channel!r}")
        if created_at is None:
            created_at = self.clock.now()
        elif created_at > self.clock.now():
            raise InvalidRequest("created_at is in the future")
        return self.store.insert(customer, amount, created_at, channel)

    def get(self, order_id):
        order = self.store.get(order_id)
        if order is None:
            raise NotFound(f"order {order_id}")
        return order

    def cancel(self, order_id):
        if self.store.get(order_id) is None:
            raise NotFound(f"order {order_id}")
        if not self.store.cancel(order_id):
            raise InvalidRequest(f"order {order_id} is already cancelled")
"""Request/response objects and parameter parsing."""
from dataclasses import dataclass, field

from orderfeed.models import InvalidRequest


@dataclass
class Request:
    method: str
    path: str
    params: dict = field(default_factory=dict)


@dataclass
class Response:
    status: int
    body: dict

    @classmethod
    def ok(cls, body):
        return cls(200, body)

    @classmethod
    def error(cls, status, code, message):
        return cls(status, {"error": code, "message": message})


def int_param(params, name, default=None, minimum=None, maximum=None):
    raw = params.get(name)
    if raw is None or raw == "":
        if default is None:
            raise InvalidRequest(f"{name} is required")
        return default
    try:
        value = int(raw)
    except (TypeError, ValueError):
        raise InvalidRequest(f"{name} must be an integer") from None
    if minimum is not None and value < minimum:
        raise InvalidRequest(f"{name} must be >= {minimum}")
    if maximum is not None and value > maximum:
        raise InvalidRequest(f"{name} must be <= {maximum}")
    return value


def str_param(params, name, default=None):
    raw = params.get(name)
    if raw is None or str(raw).strip() == "":
        if default is None:
            raise InvalidRequest(f"{name} is required")
        return default
    return str(raw).strip()

