from orderfeed.util import page_token


class FeedService:
    def __init__(self, store, settings):
        self.store = store
        self.settings = settings

    def page(self, cursor=None, limit=50):
        head = self.store.head_id()
        if cursor is None:
            token = page_token.PageToken(0, head)
        else:
            token = page_token.decode(cursor)
            page_token.ensure_current(token, head)
            # Orders at or after the last delivered one must still be exactly the
            # `offset` orders already delivered; any cancel or backdated insert in
            # that range breaks this, so the client has to start over.
            if self.store.count_active_from(token.after) != token.offset:
                raise StaleCursor("orders in the listing changed since the previous page; start again")

        # One extra row tells us whether another page exists without a second query.
        items = self.store.active_page(limit + 1, token.after)
        has_more = len(items) > limit
        items = items[:limit]
        next_cursor = None
        if has_more:
            last = items[-1]
            next_token = page_token.PageToken(
                token.offset + len(items), token.top, (last.created_at, last.id)
            )
            next_cursor = page_token.encode(next_token)
        return {"items": [o.to_dict() for o in items], "next_cursor": next_cursor}
